"""LLM-backed extraction of undeclared facts from conversation history."""

from __future__ import annotations

from importlib.resources import files
from typing import Any, Dict, List, Mapping, Optional, Set

import structlog

from rasa.mantle.llm.call_log import observe_llm_call
from rasa.mantle.llm.client import LLMClient
from rasa.mantle.memory.discovery.catalog import memory_entries_for_prompt
from rasa.mantle.memory.field import DiscoveredFact, MemoryField, PotentialMapping
from rasa.mantle.prompts.messages import (
    DEFAULT_MAX_UTTERANCES,
    LlmMessage,
    conversation_messages_from_tracker,
    llm_message,
)
from rasa.mantle.prompts.renderer import render_template
from rasa.shared.constants import ROLE_SYSTEM
from rasa.shared.core.events import UserUttered
from rasa.shared.core.trackers import DialogueStateTracker
from rasa.shared.providers.llm.llm_response import LLMResponse

structlogger = structlog.get_logger()

_DISCOVER_FACTS_TASK_TEMPLATE = (
    files("rasa.mantle.memory.discovery")
    .joinpath("discover_facts_task.jinja2")
    .read_text(encoding="utf-8")
)

TOOL_RECORD_DISCOVERED_FACTS = "record_discovered_facts"
"""Forced-shape tool name used to obtain structured extraction output."""

_RECORD_DISCOVERED_FACTS_SCHEMA: Dict[str, Any] = {
    "type": "function",
    "function": {
        "name": TOOL_RECORD_DISCOVERED_FACTS,
        "description": (
            "Record facts the customer stated that are not already covered "
            "by one of the tracked fields listed in the task instructions. "
            "Omit this call entirely if nothing new was stated."
        ),
        "parameters": {
            "type": "object",
            "properties": {
                "facts": {
                    "type": "array",
                    "description": "Zero or more newly-volunteered facts.",
                    "items": {
                        "type": "object",
                        "properties": {
                            "key": {
                                "type": "string",
                                "description": ("Short snake_case name for the fact."),
                            },
                            "value": {
                                "type": "string",
                                "description": "The stated value.",
                            },
                            "description": {
                                "type": "string",
                                "description": (
                                    "Short human-readable summary of what this "
                                    "fact means in the conversation."
                                ),
                            },
                            "confidence": {
                                "type": "number",
                                "description": (
                                    "0-1 confidence this was clearly stated."
                                ),
                            },
                            "pii": {
                                "type": "boolean",
                                "description": (
                                    "True if the value is personally identifying."
                                ),
                            },
                            "potential_mappings": {
                                "type": "array",
                                "description": (
                                    "Declared fields (from the task instructions) "
                                    "this fact could fill, if any."
                                ),
                                "items": {
                                    "type": "object",
                                    "properties": {
                                        "skill_id": {"type": "string"},
                                        "entry": {"type": "string"},
                                        "confidence": {"type": "number"},
                                    },
                                    "required": ["skill_id", "entry", "confidence"],
                                },
                            },
                        },
                        "required": ["key", "value", "confidence"],
                    },
                }
            },
            "required": ["facts"],
        },
    },
}


class ContextExtractor:
    """Spots undeclared facts and their potential cross-skill mappings."""

    def __init__(self, llm_client: LLMClient) -> None:
        self._llm_client = llm_client

    @observe_llm_call(purpose="fact discovery")
    async def _complete(
        self,
        llm_client: LLMClient,
        messages: List[LlmMessage],
        tools: Optional[List[dict]] = None,
        gated_tool_names: Optional[List[str]] = None,
    ) -> LLMResponse:
        """Discovery's completion funnel — decorated into the Inspector log.

        Discovery bypasses the orchestrator's ``_call_llm``, so this seam
        gives the call log the prompt, the ``record_discovered_facts``
        response and the latency as the provenance of the facts it produces.
        """
        return await llm_client.acompletion(messages, tools=tools)

    async def discover_facts(
        self,
        tracker: DialogueStateTracker,
        filled_scoped_entries: Set[str],
        defined_memory_fields: Mapping[str, Mapping[str, MemoryField]],
        *,
        known_discovered_keys: Optional[Set[str]] = None,
        captured_by_skill: Optional[str] = None,
        max_utterances: int = DEFAULT_MAX_UTTERANCES,
    ) -> List[DiscoveredFact]:
        """Return undeclared facts volunteered so far, with potential mappings.

        Args:
            tracker: Live tracker — source of conversation history.
            filled_scoped_entries: Scoped entries already filled
                (``skill_id.entry``) — told to the model as "already filled,
                do not repeat".
            known_discovered_keys: Keys of undeclared facts already stored —
                told to the model not to record them again.
            defined_memory_fields: ``{skill_id: {entry_name: MemoryField}}``
                of user-settable memory fields offered as ``potential_mappings``
                targets.
            captured_by_skill: Skill the user was in when they stated the fact
                (typically the flow left on a switch), stamped onto every
                returned fact for observability/audit.
            max_utterances: History window passed to the LLM (mirrors the
                main per-turn call's default).

        Returns:
            Parsed :class:`DiscoveredFact` list — empty when the LLM found
            nothing new, returned plain text instead of a tool call, or the
            call itself failed (logged, never raised).
        """
        messages = [
            llm_message(
                ROLE_SYSTEM,
                render_template(
                    _DISCOVER_FACTS_TASK_TEMPLATE,
                    filled_scoped_entries=sorted(filled_scoped_entries),
                    known_discovered_keys=sorted(known_discovered_keys or ()),
                    memory_entries=memory_entries_for_prompt(defined_memory_fields),
                ),
            )
        ]
        history, _ = conversation_messages_from_tracker(
            tracker, max_utterances=max_utterances
        )
        messages.extend(history)

        try:
            response = await self._complete(
                self._llm_client, messages, tools=[_RECORD_DISCOVERED_FACTS_SCHEMA]
            )
        except Exception as exc:
            structlogger.warning(
                "mantle.memory.discovery.extractor.discover_facts.llm_error",
                error=str(exc),
            )
            return []

        capture_turn_idx = _user_turn_count(tracker)
        facts: List[DiscoveredFact] = []
        for tool_call in response.tool_calls or []:
            if tool_call.tool_name != TOOL_RECORD_DISCOVERED_FACTS:
                continue
            for raw_fact in tool_call.tool_args.get("facts", []) or []:
                fact = _parse_discovered_fact(
                    raw_fact, capture_turn_idx, captured_by_skill
                )
                if fact is not None:
                    facts.append(fact)
        return facts


def _user_turn_count(tracker: DialogueStateTracker) -> int:
    """Return the number of user turns so far — freshness anchor for new facts.

    Stamped once on each newly captured :class:`DiscoveredFact`; stored facts
    are not updated on later turns — readers compare this to the current turn
    count when applying freshness windows.
    """
    events = getattr(tracker, "events", None) or []
    return sum(1 for event in events if isinstance(event, UserUttered))


def _parse_discovered_fact(
    raw: Any, turn_idx: int, captured_by_skill: Optional[str]
) -> Optional[DiscoveredFact]:
    """Validate one raw ``facts[]`` entry into a :class:`DiscoveredFact`.

    Malformed ``potential_mappings`` entries are dropped individually so one
    bad mapping does not discard an otherwise valid fact.
    """
    if not isinstance(raw, dict):
        return None
    fact_key = raw.get("key")
    try:
        return DiscoveredFact(
            key=raw["key"],
            value=raw["value"],
            description=str(raw.get("description") or ""),
            turn_idx=turn_idx,
            confidence=float(raw.get("confidence", 1.0)),
            pii=bool(raw.get("pii", False)),
            captured_by_skill=captured_by_skill,
            potential_mappings=_parse_potential_mappings(
                raw.get("potential_mappings", []) or [],
                fact_key=fact_key if isinstance(fact_key, str) else None,
            ),
        )
    except Exception:
        structlogger.warning(
            "mantle.memory.discovery.extractor.discover_facts.invalid_fact",
            fact_key=fact_key if isinstance(fact_key, str) else None,
        )
        return None


def _parse_potential_mappings(
    raw_mappings: Any,
    *,
    fact_key: Optional[str],
) -> list[PotentialMapping]:
    """Return validated mappings, skipping malformed entries."""
    if not isinstance(raw_mappings, list):
        structlogger.warning(
            "mantle.memory.discovery.extractor.discover_facts.invalid_mappings",
            fact_key=fact_key,
            mappings_type=type(raw_mappings).__name__,
        )
        return []

    mappings: list[PotentialMapping] = []
    for index, raw_mapping in enumerate(raw_mappings):
        try:
            mappings.append(PotentialMapping.model_validate(raw_mapping))
        except Exception:
            structlogger.warning(
                "mantle.memory.discovery.extractor.discover_facts.invalid_mapping",
                fact_key=fact_key,
                mapping_index=index,
            )
    return mappings
